ALTER TABLE "Destination" ADD COLUMN "metaDescription" TEXT;

UPDATE "Destination" SET "metaDescription" = $d$Visit Bumthang, Bhutan's spiritual heartland: Jambay Lhakhang, Kurjey Lhakhang, Tamshing, local cheese and honey. Guided tours and custom trips.$d$ WHERE "slug" = 'bumthang' AND "metaDescription" IS NULL;
UPDATE "Destination" SET "metaDescription" = $d$Explore Chukha, Bhutan: forested gorges along the Phuentsholing–Thimphu road, Chukha Dzong and the hydropower heartland. Guides and tours arranged.$d$ WHERE "slug" = 'chukha' AND "metaDescription" IS NULL;
UPDATE "Destination" SET "metaDescription" = $d$Discover Dagana, Bhutan: remote terraced hillsides, orange orchards and Daga Dzong, far from the usual tourist trail. Custom trips with a local guide.$d$ WHERE "slug" = 'dagana' AND "metaDescription" IS NULL;
UPDATE "Destination" SET "metaDescription" = $d$Visit Gasa, Bhutan's most remote district: Gasa Dzong, natural hot springs and the gateway to high-altitude treks. Guided tours and treks arranged.$d$ WHERE "slug" = 'gasa' AND "metaDescription" IS NULL;
UPDATE "Destination" SET "metaDescription" = $d$Visit Haa Valley, Bhutan: pristine landscapes, Chele La Pass views and the twin temples of Lhakhang Karpo and Nagpo. Day trips and tours with a guide.$d$ WHERE "slug" = 'haa' AND "metaDescription" IS NULL;
UPDATE "Destination" SET "metaDescription" = $d$Visit Lhuentse, ancestral home of Bhutan's royal family: Lhuentse Dzong and the Kurtoep weaving villages known for fine textiles. Guided eastern tours.$d$ WHERE "slug" = 'lhuentse' AND "metaDescription" IS NULL;
UPDATE "Destination" SET "metaDescription" = $d$Visit Mongar, the gateway to eastern Bhutan: Mongar Dzong and a dramatic mountain highway from Bumthang. Guided eastern Bhutan tours and custom trips.$d$ WHERE "slug" = 'mongar' AND "metaDescription" IS NULL;
