UPDATE "Destination" SET "metaDescription" = $d$Discover Pemagatshel, one of Bhutan's least-visited districts: Pemagatshel Dzong, rolling hills and farming villages. Custom trips with a local guide.$d$ WHERE "slug" = 'pemagatshel' AND "metaDescription" IS NULL;
UPDATE "Destination" SET "metaDescription" = $d$Visit Punakha, Bhutan's former winter capital: Punakha Dzong, the suspension bridge and Chimi Lhakhang. Guided tours and Bhutan packages from DTT.$d$ WHERE "slug" = 'punakha' AND "metaDescription" IS NULL;
UPDATE "Destination" SET "metaDescription" = $d$Visit Samdrup Jongkhar, Bhutan's southeastern gateway to Assam at the end of the east–west highway. Custom trips and border arrangements with DTT.$d$ WHERE "slug" = 'samdrup-jongkhar' AND "metaDescription" IS NULL;
UPDATE "Destination" SET "metaDescription" = $d$Discover Samtse, Bhutan: tea gardens, lowland forest, the Dorokha region and border trade routes in the south-west. Custom trips with a local guide.$d$ WHERE "slug" = 'samtse' AND "metaDescription" IS NULL;
UPDATE "Destination" SET "metaDescription" = $d$Visit Sarpang, Bhutan's southern gateway near Gelephu: subtropical plains on the Assam border and a base for jungle trips. Custom tours with a guide.$d$ WHERE "slug" = 'sarpang' AND "metaDescription" IS NULL;
UPDATE "Destination" SET "metaDescription" = $d$Visit Thimphu, Bhutan's capital: Tashichho Dzong, Buddha Dordenma, Memorial Chorten and the weekend market. Guided Thimphu tours and Bhutan packages.$d$ WHERE "slug" = 'thimphu' AND "metaDescription" IS NULL;
UPDATE "Destination" SET "metaDescription" = $d$Visit Trashigang, eastern Bhutan's largest district: Trashigang Dzong, the Gom Kora sacred site and old trade routes. Guided eastern tours with DTT.$d$ WHERE "slug" = 'trashigang' AND "metaDescription" IS NULL;
UPDATE "Destination" SET "metaDescription" = $d$Visit Trashiyangtse, Bhutan: Chorten Kora, traditional wood-turning crafts and Bomdeling Wildlife Sanctuary. Quiet eastern tours with a local guide.$d$ WHERE "slug" = 'trashiyangtse' AND "metaDescription" IS NULL;
UPDATE "Destination" SET "metaDescription" = $d$Visit Trongsa, ancestral seat of Bhutan's royal family: Trongsa Dzong above the Mangde gorge and the Royal Heritage Museum. Guided tours with DTT.$d$ WHERE "slug" = 'trongsa' AND "metaDescription" IS NULL;
UPDATE "Destination" SET "metaDescription" = $d$Discover Tsirang, Bhutan's youngest district: citrus orchards and gentle rolling hills at a slow pace. Custom trips with a licensed local guide from DTT.$d$ WHERE "slug" = 'tsirang' AND "metaDescription" IS NULL;
UPDATE "Destination" SET "metaDescription" = $d$Visit Wangdue Phodrang and the Phobjikha Valley, Bhutan: Gangtey Monastery and wintering black-necked cranes. Guided tours and treks from DTT.$d$ WHERE "slug" = 'wangdue-phodrang' AND "metaDescription" IS NULL;
UPDATE "Destination" SET "metaDescription" = $d$Visit Zhemgang, Bhutan's biodiversity hotspot: Royal Manas National Park, Zhemgang Dzong and golden langur habitat. Guided wildlife tours with DTT.$d$ WHERE "slug" = 'zhemgang' AND "metaDescription" IS NULL;
